-- Detection rules: Secrets (timeplus-io/apps#86).
-- Secrets in what the agent sends (commands, prompts), in what it reads (credential files) and in what comes back (tool results, replies).
-- The message names the kind of secret and its first characters, never the whole value.
-- One row is written per rule that matches, under the rule's own id and severity. A regex in a SQL
-- string needs every backslash doubled: a single \b is a backspace character, and the pattern never matches.
-- Command rules read the command of a shell tool call, not the text of a file being written or read.
CREATE MATERIALIZED VIEW IF NOT EXISTS {{ .DB }}.mv_rule_secrets
INTO {{ .DB }}.agentguard_security_events AS
SELECT
  event_time     AS detected_at,
  rule_id,
  rule_name,
  severity,
  agent_id,
  deployment_id,
  session_id,
  run_id,
  raw_hook_name  AS hook_name,
  tool_name,
  concat(rule_name, ': ', evidence) AS message,
  raw_event_data AS event_data
FROM {{ .DB }}.agentguard_cim_event
ARRAY JOIN
  ['secret.sent', 'secret.file', 'secret.exposed', 'secret.assigned', 'secret.prompt'] AS rule_id,
  ['Secret in a command', 'Credential file accessed', 'Secret in a tool result or reply', 'Key assigned in a tool result or reply', 'Secret in a prompt'] AS rule_name,
  ['high', 'medium', 'high', 'medium', 'medium'] AS severity,
  [
    -- secret.sent
    (event_type = 'tool_invoke' AND (match(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '(?:^|[^A-Za-z0-9]|\\\\[nrt])(ghp_[A-Za-z0-9]{36}\\b|github_pat_[A-Za-z0-9_]{40,}|sk-ant-[A-Za-z0-9_\\-]{20,}|AKIA[0-9A-Z]{16}\\b|sk-[A-Za-z0-9]{32,}\\b|AIza[0-9A-Za-z_\\-]{35}\\b|Bearer\\s+[A-Za-z0-9._~+/\\-]{20,}|eyJ[A-Za-z0-9_\\-]{10,}\\.eyJ[A-Za-z0-9_\\-]{10,}\\.[A-Za-z0-9_\\-]{10,}|-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----|(?i:aws_secret_access_key)\\s*[=:]\\s*\\S{20,})') OR match(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '\\b(curl|wget|http|https|xh)\\b[^;&|]*(\\s-u|--user)\\s+[\\"\']?[A-Za-z0-9_.@\\-]+:[^\\s\\"\'$:]{3,}') OR match(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '[a-z][a-z0-9+.\\-]*://[^/\\s:@\\"\']+:[^@\\s$\\"\']{3,}@[A-Za-z0-9]') OR match(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '\\b(mysql|mariadb)\\b[^;&|]*\\s-p[^\\s\\-][^\\s]{3,}'))),
    -- secret.file
    (event_type = 'tool_invoke' AND ((lower(tool_name) IN ('bash', 'shell', 'exec', 'run_terminal_cmd', 'local_shell', 'terminal', 'computer') AND match(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '(\\.ssh/(id_[a-z0-9_]+|authorized_keys)|\\.aws/credentials|\\.netrc\\b|\\.npmrc\\b|\\.pypirc\\b|\\.docker/config\\.json|\\.kube/config|(^|[/\\s\\"\'=])\\.env(\\.[a-z]+)?(\\b|$)|/etc/(shadow|sudoers))')) OR match(multi_if(json_value(tool_input, '$[0].file_path') != '', json_value(tool_input, '$[0].file_path'), json_value(tool_input, '$.file_path') != '', json_value(tool_input, '$.file_path'), json_value(tool_input, '$.path')), '(\\.ssh/(id_[a-z0-9_]+|authorized_keys)|\\.aws/credentials|\\.netrc\\b|\\.npmrc\\b|\\.pypirc\\b|\\.docker/config\\.json|\\.kube/config|(^|[/\\s\\"\'=])\\.env(\\.[a-z]+)?(\\b|$)|/etc/(shadow|sudoers))'))),
    -- secret.exposed
    (event_type IN ('tool_complete', 'llm_response') AND (tool_result NOT LIKE '[{"type":"image"%' AND match(concat(tool_result, ' ', assistant_message), '(?:^|[^A-Za-z0-9]|\\\\[nrt])(ghp_[A-Za-z0-9]{36}\\b|github_pat_[A-Za-z0-9_]{40,}|sk-ant-[A-Za-z0-9_\\-]{20,}|AKIA[0-9A-Z]{16}\\b|sk-[A-Za-z0-9]{32,}\\b|AIza[0-9A-Za-z_\\-]{35}\\b|Bearer\\s+[A-Za-z0-9._~+/\\-]{20,}|eyJ[A-Za-z0-9_\\-]{10,}\\.eyJ[A-Za-z0-9_\\-]{10,}\\.[A-Za-z0-9_\\-]{10,}|-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----|(?i:aws_secret_access_key)\\s*[=:]\\s*\\S{20,})'))),
    -- secret.assigned
    (event_type IN ('tool_complete', 'llm_response') AND (tool_result NOT LIKE '[{"type":"image"%' AND match(concat(tool_result, ' ', assistant_message), '(?i)\\b(api[_-]?key|secret[_-]?key|access[_-]?key|client[_-]?secret)\\b[\\\\\\"\\x27]{0,2}\\s*[=:]\\s*[\\\\\\"\\x27]{0,2}[A-Za-z0-9_\\-/+]{16,}'))),
    -- secret.prompt
    (event_type = 'user_input' AND (match(user_message, '(?:^|[^A-Za-z0-9]|\\\\[nrt])(ghp_[A-Za-z0-9]{36}\\b|github_pat_[A-Za-z0-9_]{40,}|sk-ant-[A-Za-z0-9_\\-]{20,}|AKIA[0-9A-Z]{16}\\b|sk-[A-Za-z0-9]{32,}\\b|AIza[0-9A-Za-z_\\-]{35}\\b|Bearer\\s+[A-Za-z0-9._~+/\\-]{20,}|eyJ[A-Za-z0-9_\\-]{10,}\\.eyJ[A-Za-z0-9_\\-]{10,}\\.[A-Za-z0-9_\\-]{10,}|-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----|(?i:aws_secret_access_key)\\s*[=:]\\s*\\S{20,})') OR match(user_message, '(?i)\\bpass(word|wd)?\\b\\s*(is\\s+|[:=]\\s*)[^\\s,;]{6,}|\\bpassword\\s+[^\\s,;]*[0-9!@#$%^&*][^\\s,;]*')))
  ] AS hit,
  [
    -- secret.sent
    multi_if(match(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '(?:^|[^A-Za-z0-9]|\\\\[nrt])(ghp_[A-Za-z0-9]{36}\\b|github_pat_[A-Za-z0-9_]{40,}|sk-ant-[A-Za-z0-9_\\-]{20,}|AKIA[0-9A-Z]{16}\\b|sk-[A-Za-z0-9]{32,}\\b|AIza[0-9A-Za-z_\\-]{35}\\b|Bearer\\s+[A-Za-z0-9._~+/\\-]{20,}|eyJ[A-Za-z0-9_\\-]{10,}\\.eyJ[A-Za-z0-9_\\-]{10,}\\.[A-Za-z0-9_\\-]{10,}|-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----|(?i:aws_secret_access_key)\\s*[=:]\\s*\\S{20,})'), concat(multi_if(match(extract(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '(?:^|[^A-Za-z0-9]|\\\\[nrt])(ghp_[A-Za-z0-9]{36}\\b|github_pat_[A-Za-z0-9_]{40,}|sk-ant-[A-Za-z0-9_\\-]{20,}|AKIA[0-9A-Z]{16}\\b|sk-[A-Za-z0-9]{32,}\\b|AIza[0-9A-Za-z_\\-]{35}\\b|Bearer\\s+[A-Za-z0-9._~+/\\-]{20,}|eyJ[A-Za-z0-9_\\-]{10,}\\.eyJ[A-Za-z0-9_\\-]{10,}\\.[A-Za-z0-9_\\-]{10,}|-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----|(?i:aws_secret_access_key)\\s*[=:]\\s*\\S{20,})'), '^(ghp_|github_pat_)'), 'GitHub token', match(extract(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value(tool_input, '$.command'), tool_input), '(?:^|[^A-Za-z0-9]|\\\\[nrt])(ghp_[A-Za-z0-9]{36}\\b|github_pat_[A-Za-z0-9_]{40,}|sk-ant-[A-Za-z0-9_\\-]{20,}|AKIA[0-9A-Z]{16}\\b|sk-[A-Za-z0-9]{32,}\\b|AIza[0-9A-Za-z_\\-]{35}\\b|Bearer\\s+[A-Za-z0-9._~+/\\-]{20,}|eyJ[A-Za-z0-9_\\-]{10,}\\.eyJ[A-Za-z0-9_\\-]{10,}\\.[A-Za-z0-9_\\-]{10,}|-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----|(?i:aws_secret_access_key)\\s*[=:]\\s*\\S{20,})'), '^sk-ant-'), 'Anthropic API key', match(extract(multi_if(json_value(tool_input, '$[0].command') != '', json_value(tool_input, '$[0].command'), json_value(tool_input, '$.command') != '', json_value